// 一次实质探听的内容由当前作者声明决定；没有任意人物/位置/答复/奖励参数。
#include "contact_inquiry_boundary.hpp"
#include "resident/kernel/command_types.hpp"
#include <set>
namespace hanmo::resident {
Outcome<ContactInquiryRequest> decode_contact_inquiry_command(const StableId& kind,const BoundaryValue& value){try{using namespace boundary;if(kind!=contact_inquiry_action_kind)unsupported("UnsupportedContactInquiryCommand",kind);std::set<StableId> names;for(const auto& row:object(value,kind))if(!names.insert(row.first).second)fail("DuplicateContactInquiryCommandField",row.first);fields(value,{"policy_id"},{},kind);const auto id=get_string(value,"policy_id",kind);if(id.empty()||id.size()>256)fail("InvalidContactInquiryCommand",kind);return {true,{id},{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_contact_inquiry_command(const ContactInquiryRequest& request){return boundary::obj({{"policy_id",BoundaryValue{request.policy_id}}});}
BoundaryValue encode_contact_inquiry_quote(const ContactInquiryQuote& quote){return boundary::obj({{"duration",BoundaryValue{quote.duration_ticks}},{"policy_id",BoundaryValue{quote.policy_id}},{"subject_actor_id",BoundaryValue{quote.subject_actor_id}},{"provider_actor_id",BoundaryValue{quote.consent.meeting.provider_actor_id}}});}
ActionCompletion contact_inquiry_completion(const ContactInquiryCompletion& source){ActionCompletion result;result.completed=true;result.success=source.success;result.code=source.success?StableId{"ContactInquiryAnswered"}:source.reason;return result;}
Outcome<Integer> decode_contact_inquiry_profile_version(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){try{using namespace boundary;std::set<StableId> names;for(const auto& row:object(scenario,"scenario"))if(!names.insert(row.first).second)fail("DuplicateContactInquiryField",row.first);const auto* profile=scenario.find("contact_inquiry_profile");const auto* source=scenario.find("contact_inquiries");if(!profile){if(source)unsupported("ContactInquiryProfileRequired","contact_inquiries");return {true,0,{}};}const auto& chosen=string(*profile,"contact_inquiry_profile");const Integer version=chosen=="witnessed_personal_inquiries_v1"?1:chosen=="witnessed_personal_inquiries_time2_v2"?2:0;if(!version)unsupported("UnsupportedContactInquiryProfile","contact_inquiry_profile");if(!source)unsupported("ContactInquiryCatalogRequired","contact_inquiries");if(get_int(*source,"version","contact_inquiries")!=version)unsupported("ContactInquiryCatalogVersionMismatch","contact_inquiries");for(const auto* cap:{version==1?"contact_inquiries_v1":"contact_inquiries_v2","dialogue","multi_actor","native_dynamic_world"})if(std::find(capabilities.begin(),capabilities.end(),cap)==capabilities.end())unsupported("ContactInquiryCapabilityRequired",cap);const auto* dynamic=scenario.find("dynamic_world");if(!dynamic||get_string(*dynamic,"profile","dynamic_world")!="local_society_v1")unsupported("ContactInquiryNativeProfileRequired","dynamic_world");const auto* appointment=scenario.find("personal_appointment_profile");const auto* message=scenario.find("task_message_handoff_profile");const bool direct_appointment=appointment&&string(*appointment,"personal_appointment_profile")== (version==1?"witnessed_personal_meetings_v1":"witnessed_personal_meetings_time2_v2");const bool direct_message=message&&(string(*message,"task_message_handoff_profile")=="observed_letter_delivery_v1"||string(*message,"task_message_handoff_profile")=="observed_letter_delivery_and_report_v2"||string(*message,"task_message_handoff_profile")=="known_personal_delivery_and_report_v3"||string(*message,"task_message_handoff_profile")=="known_personal_delivery_and_sender_report_v4");if(!direct_appointment&&!direct_message)unsupported("ContactInquiryDirectSourceRequired","contact_inquiries");return {true,version,{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<bool> decode_contact_inquiry_profile(const BoundaryValue&s,const std::vector<StableId>&c){auto v=decode_contact_inquiry_profile_version(s,c);if(!v.ok)return {false,{},v.error};return {true,v.value!=0,{}};}
Status validate_contact_inquiry_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const ContactInquiryCatalog* catalog,const ContactInquiryState* state){Integer count=0;bool direct=false;for(const auto& m:modules){if(m.first==contact_inquiry_module){++count;if(!catalog||m.second!=std::to_string(catalog->version))return common_failure("UnsupportedContactInquiryVersion");}if((m.first==personal_appointment_module&&catalog&&m.second==std::to_string(catalog->version))||(m.first=="task_message_handoffs"&&(m.second=="1"||m.second=="2"||m.second=="3"||m.second=="4")))direct=true;}if(count!=(catalog?1:0)||bool(catalog)!=bool(state)||(catalog&&(!direct||(catalog->version!=1&&catalog->version!=2)))||(state&&state->version!=catalog->version))return common_failure("ContactInquiryProfileMismatch");if(state)return common_success();for(const auto& row:common.state().facts.rows())if(row.second.domain==contact_inquiry_module||row.second.kind==contact_inquiry_started_kind||row.second.kind==contact_inquiry_finished_kind)return common_failure("ContactInquiryProfileRequired",row.first);for(const auto& row:common.state().actions.rows())if(row.second.kind==contact_inquiry_action_kind)return common_failure("ContactInquiryProfileRequired",row.first);return validate_contact_inquiry_cached_results(common,nullptr);}
}
